style.css:
/* Sweet Pastel Dream — Pinterest */

:root {
  /* Puedes cambiar estos colores */
  --my-pink: #f6dce5;
  --my-pink-light: #fff0f4;
  --my-yellow: #fff0bd;
  --my-beige: #f5eadb;
  --my-cream: #fffaf3;
  --my-brown: #806b60;
}

/* fondo general */
html,
body {
  background: var(--my-cream) !important;
}

/* textos */
body,
button,
input,
textarea {
  color: var(--my-brown) !important;
  font-family: "Trebuchet MS", sans-serif !important;
}

/* enlaces */
a {
  color: #c77f9c !important;
}

/* campos de búsqueda */
input,
textarea {
  background: var(--my-pink-light) !important;
  border: 1px solid var(--my-pink) !important;
  border-radius: 18px !important;
}

/* botones */
button {
  border-radius: 18px !important;
}

/* imágenes y pines */
img {
  border-radius: 14px !important;
}

/* barras y paneles */
header,
nav,
[role="navigation"] {
  background-color: var(--my-cream) !important;
}

/* selección de texto */
::selection {
  background: var(--my-yellow) !important;
  color: var(--my-brown) !important;
}

/* barra de desplazamiento */
::-webkit-scrollbar-thumb {
  background: var(--my-pink) !important;
  border-radius: 20px !important;
}

::-webkit-scrollbar-track {
  background: var(--my-cream) !important;
}
